source:
(sh, r) => {
    prev?.call(mat, sh, r);
    Object.assign(sh.uniforms, U);
    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nvarying vec3 vCutW; varying float vCutUp;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\n vCutW = (modelMatrix * vec4(transformed, 1.)).xyz; vCutUp = abs(normalize(mat3(modelMatrix) * normal).y);');
    sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nvarying vec3 vCutW; varying float vCutUp; uniform vec3 uCutC, uCutP; uniform float uCutOn;')
      .replace('#include <clipping_planes_fragment>', `#include <clipping_planes_fragment>
        if (uCutOn > .01 && vCutUp < .7) {
          vec3 ab = uCutP - uCutC; float L = length(ab); vec3 d = ab / max(L, 1e-3); float t = dot(vCutW - uCutC, d);
          if (t > .2 && t < L - .5) {
            float R = mix(.25, .6, clamp(t / L, 0., 1.)), r = length(vCutW - (uCutC + d * t));
            float a = smoothstep(R, R - .3, r) * uCutOn;
            vec2 q = floor(mod(gl_FragCoord.xy, 4.)); float bay = (mod(q.x + q.y * 2., 4.) * 4. + mod(q.x * 3. + q.y, 4.)) / 16.;   // (a 4x4 dither: the edge reads as a soft dissolve)
            if (a > bay + .03) discard;
          }
        }`);
  }

